theorem crossing_measurable (n m : ℕ) (T ε : ℝ≥0) :
    MeasurableSet {ω | ∃ t : ℝ≥0, t ≤ T ∧
      (ε : ℝ) < ‖compensatedPath n ω t - compensatedPath m ω t‖}

theorem measure_ext_initial {μ ν : Measure ℝ≥0}
    (hfinite : ∀ t : ℝ≥0, μ (Iic t) ≠ ∞)
    (heq : ∀ t : ℝ≥0, μ (Iic t) = ν (Iic t)) : μ = ν

theorem coincidence_probability (κ t : ℝ≥0) :
    sourceMeasure {w | leftPath κ w t=rightPath κ w t}=
      gaussianProduct {w | changedPath κ w t=0}

theorem resolvent_norm_bound {κ : ℝ≥0} (hκ : 0 < κ) {F G : C₀(ℝ, ℝ)}
    (h : Admissible κ F G) {q : ℝ} (hq : 0 < q) :
    q*‖F‖ ≤ ‖q • F-G‖

theorem add {κ : ℝ≥0} {F G H K : C₀(ℝ, ℝ)}
    (h : Admissible κ F G) (h' : Admissible κ H K) :
    Admissible κ (F+H) (G+K)

theorem sub {κ : ℝ≥0} {F G H K : C₀(ℝ, ℝ)}
    (h : Admissible κ F G) (h' : Admissible κ H K) :
    Admissible κ (F-H) (G-K)

theorem resolvent_stability {κ : ℝ≥0} (hκ : 0 < κ) {F G H K : C₀(ℝ, ℝ)}
    (h : Admissible κ F G) (h' : Admissible κ H K) {q : ℝ} (hq : 0 < q) :
    q*‖F-H‖ ≤ ‖(q • F-G)-(q • H-K)‖

theorem resolvent_injective {κ : ℝ≥0} (hκ : 0 < κ) {F G H K : C₀(ℝ, ℝ)}
    (h : Admissible κ F G) (h' : Admissible κ H K) {q : ℝ} (hq : 0 < q)
    (he : q • F - G = q • H - K) : F = H
